:root {
  --ink: #283044;
  --paper: #fffaf1;
  --pink: #f05b93;
}

.skate-tag {
  display: flex;
  width: 460px;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
}

.tag-icon {
  display: grid;
  width: 88px;
  place-items: center;
  background: var(--pink);
  font-size: 38px;
}

.tag-content {
  flex: 1;
  padding: 15px 18px;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--pink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.2;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
  color: var(--ink);
  font-size: 13px;
}

.tag-footer strong {
  color: var(--pink);
  font-size: 14px;
}
